export default tormenta20;

export const calcMod2 = calcMod;

export const skillTotal = (
  attrValue: number,
  trained: boolean,
  level: number,
): number => {
  const mod = calcMod(attrValue);
  const trainingBonus = trained ? 4 + Math.floor(level / 2) : 0;
  return mod + trainingBonus;
};
